import{_ as t,o,c as d,a2 as a}from"./chunks/framework.YKbyQ3zk.js";const g=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}'),r={name:"troubleshooting.md"};function s(n,e,i,h,c,l){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>This page is for whoever is looking at a failed sign-in, a log line or a browser console message. Find the symptom, read what it means and do the fix. Every error code is listed on the <a href="./reference/errors.html">error reference</a>. Run <code>pnpm exec evo-auth check</code> (with npm, <code>npx @evo-auth/core check</code>) first: it names missing and weak settings without printing a value.</p><h2 id="start-up-and-environment" tabindex="-1">Start-up and environment <a class="header-anchor" href="#start-up-and-environment" aria-label="Permalink to &quot;Start-up and environment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>What it means</th><th>Fix</th></tr></thead><tbody><tr><td>Every auth route answers 503 <code>unavailable</code> on Convex, and the log repeats <code>[evo-auth] register_routes.setup_failed &lt;NAMES&gt;</code>.</td><td>A variable is missing or refused, or <code>EVO_AUTH_PROXY_SECRET</code> is unset outside the development cookie mode. The line repeats on every refused request until the environment is fixed. Your app&#39;s other routes still serve.</td><td>Set the named variables, push if you changed code, then run <code>evo-auth check</code>. A changed variable applies from the next request, with no push.</td></tr><tr><td><code>npx convex dev</code> fails on the first push, naming <code>EVO_AUTH_PUBLIC_KEYS</code>.</td><td><code>auth.config.ts</code> reads it when it loads, and the deployment did not exist yet when you could set it.</td><td>Set <code>EVO_AUTH_PUBLIC_KEYS</code> on the deployment, then push again.</td></tr><tr><td>The app server answers every request with Start&#39;s generic 500, with no <code>Cache-Control</code> or <code>Vary</code>.</td><td>A required variable is missing on the app server. The module that builds the proxy fails before the middleware runs.</td><td>Read the server log: it names the variable and never its value. Set it and restart.</td></tr><tr><td><code>evo-auth init</code> or <code>keys generate</code> refuses.</td><td>Git does not confirm the env file is ignored, the file is a link, a key is already there, or <code>evo-auth.config.ts</code> already exists.</td><td>Read the message: it names the file and the rule. Add the file to <code>.gitignore</code>. Use <code>keys rotate</code> instead of <code>keys generate</code> to change keys.</td></tr><tr><td><code>evo-auth check</code> exits 1 with <code>the JWKS at … could not be reached</code>.</td><td><code>check</code> compares your keys with the JWKS your app publishes at <code>{publicUrl}/.well-known/jwks.json</code>, and nothing answers there: the app is not running, or <code>publicUrl</code> points at the wrong address.</td><td>Start the app and run <code>check</code> again. The other sections of the report are still valid.</td></tr><tr><td><code>fromEnv</code> refuses a variable that is set but empty.</td><td>An empty value counts as an error.</td><td>Remove the line, or give it a value. In <code>.env.example</code> the optional variables are commented out for this reason.</td></tr></tbody></table><h2 id="answers-from-the-auth-endpoints" tabindex="-1">Answers from the auth endpoints <a class="header-anchor" href="#answers-from-the-auth-endpoints" aria-label="Permalink to &quot;Answers from the auth endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Status</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>proxy_refused</code></td><td>403</td><td>The two sides hold different <code>EVO_AUTH_PROXY_SECRET</code> values, a request skipped the proxy, or <code>clientAddress</code> returned something that is not one IP literal. The proxy logs <code>proxy.client_address_refused</code>.</td><td>Set the same secret on both sides. Check <code>clientAddress</code>: <a href="./proxy-and-client-address.html">the proxy page</a>.</td></tr><tr><td><code>origin_refused</code></td><td>403</td><td>A POST carried a missing, <code>null</code> or unlisted <code>Origin</code>.</td><td>Add the page&#39;s exact origin to <code>allowedOrigins</code>.</td></tr><tr><td><code>rate_limited</code></td><td>429</td><td>A bucket is full. <code>Retry-After</code> says for how long.</td><td>Wait. If real users hit it, check that <code>clientAddress</code> gives each user their own address: behind a load balancer the socket address is the balancer&#39;s.</td></tr><tr><td><code>oauth_failed</code></td><td>400</td><td>The sign-in cookie was missing, expired or altered, the state did not match, or the provider refused.</td><td>Start again. Check the callback URL and credentials on <a href="./github-oauth-app.html">GitHub&#39;s side</a>.</td></tr><tr><td><code>refresh_reuse</code></td><td>401</td><td>An old refresh token was used again. The session was revoked.</td><td>The user signs in again. If it happens without theft, look for a client that retries a refresh after the grace window, or a database restore.</td></tr><tr><td><code>signing_failed</code></td><td>503</td><td>The active signing key is missing from the public set.</td><td>Run <code>evo-auth check</code> and fix the keys.</td></tr><tr><td><code>reverification_required</code></td><td>403</td><td>The action needs a recent confirmation with the provider.</td><td>The user confirms with the provider, then repeats the action. The components do this.</td></tr><tr><td><code>method_not_allowed</code></td><td>405</td><td>The method is not answered there. <code>OPTIONS</code> always is: there is no CORS. <code>Allow</code> lists what is.</td><td>Use a listed method.</td></tr><tr><td><code>not_found</code></td><td>404</td><td>The path is not an auth path as written: wrong case, a trailing or doubled slash, an encoded segment, or a query on a route that takes none.</td><td>Use the exact paths in <a href="./configuration.html#the-routes">Configuration</a>. Start answers <code>/AUTH/...</code> with a 404 from the proxy and <code>//auth/...</code> with its own 308.</td></tr></tbody></table><h2 id="signed-out-when-you-did-not-expect-it" tabindex="-1">Signed out when you did not expect it <a class="header-anchor" href="#signed-out-when-you-did-not-expect-it" aria-label="Permalink to &quot;Signed out when you did not expect it&quot;">​</a></h2><ul><li>Everyone signed out at once: <code>EVO_AUTH_SECRET</code> was replaced, or <code>basePath</code> was changed to a path nested under the old one (once each). See <a href="./rotating-secrets.html">Rotating secrets</a>.</li><li>A page shows signed out, with new tokens seen as <code>unknown_kid</code>: the server&#39;s public key set lacks the active key&#39;s id. <code>getAuth</code> sends the handshake, and the loop guard ends it signed out. Set the new <code>EVO_AUTH_PUBLIC_KEYS</code> on that server and run <code>evo-auth check</code>.</li><li>One session signed out after a restore: a restore from backup signs users out.</li></ul><h2 id="browser-console-lines-that-are-expected" tabindex="-1">Browser console lines that are expected <a class="header-anchor" href="#browser-console-lines-that-are-expected" aria-label="Permalink to &quot;Browser console lines that are expected&quot;">​</a></h2><p>These are normal and need no fix:</p><ul><li>A <code>401</code> on <code>/auth/token</code> after &quot;Sign out everywhere&quot; or after deleting the account. The session is gone, so the refresh is refused, and the provider signs the tab out.</li><li>A <code>403</code> <code>reverification_required</code> before an account delete. The user has not confirmed with the provider recently enough; the dialog then sends them to the provider.</li><li>Requests shown as aborted when the page navigates away.</li></ul><h2 id="the-page-and-the-policy" tabindex="-1">The page and the policy <a class="header-anchor" href="#the-page-and-the-policy" aria-label="Permalink to &quot;The page and the policy&quot;">​</a></h2><ul><li><strong>Sign-in does nothing, and the console shows a form-action violation.</strong> Sign-in was started from a form. With <code>form-action &#39;self&#39;</code>, Chrome blocks the redirect that follows a form submission. Use <code>SignInButton</code> or a link.</li><li><strong>Avatars are missing.</strong> <code>img-src</code> must allow <code>https:</code> or the avatar host.</li><li><strong>A provider button shows an empty square, and the console shows an img-src violation.</strong> The provider logos are <code>data:</code> images: add <code>data:</code> to <code>img-src</code>. It is needed only when a provider has an icon, as <code>github()</code> and <code>google()</code> do.</li><li><strong>Components have no styling, or a style violation appears.</strong> Import <code>@evo-auth/react/styles.css</code> from your own origin, and allow <code>style-src &#39;self&#39;</code>.</li><li><strong>A hook sees <code>user.id</code> as undefined.</strong> A hook receives the stored document: use <code>user._id</code>. The server API returns <code>user.id</code>.</li><li><strong>The page keeps showing the previous user after you signed in as someone else in another tab.</strong> Reload on <code>useAuth().identityChanged</code>: <a href="./react.html#another-tab-signs-in-as-someone-else">React guide</a>.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./security-model.html">Security model</a></li><li><a href="./command-line.html">The command line</a></li></ul>',15)])])}const p=t(r,[["render",s]]);export{g as __pageData,p as default};
